contract InvMutTest {
    C c;

    bool public reject;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool _reject) public payable {
        reject = _reject;

        c.withdrawReward(address(this)); if (__ESBMC_reverted()) return;

        assert(c._locked() == false);
    }

    receive() external payable {
        require(!reject, "rejecting Ether");
    }
}

