// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;
    bool public reject;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(bool _reject) internal {
        reject = _reject;
        try c.withdrawReward(address(this)) {} catch { return; }
        assertTrue(c._locked() == false);
    }

    function testFuzz_run(bool _reject) public {
        _run(_reject);
    }

    receive() external payable {
        require(!reject, "rejecting Ether");
    }
}
